// West Bengal — 18th West Bengal Vidhan Sabha (matdan 23 + 29 Apr 2026, parinaam 4 May 2026; karyakaal 2026-2031).
// 2026 parinaam: BJP 207, AITC 80, INC 2, AJUP 2, CPI(M) 1, AISF 1 = 294 (Falta ka 4 May ko parinaam ghoshit nahi hua tha).
// Falta repoll (24 May 2026): Debangshu Panda (BJP) = BJP 208.
// Oct 2026 upchunav (counting 9 Oct 2026): Nandigram — Hasirani Rath (BJP; Suvendu Adhikari ne 13 May 2026 ko resign kiya),
// Rejinagar — Sakharav Sarkar (BJP; Humayun Kabir ne Naoda retain karke resign kiya) = BJP 209.
// Rajarhat New Town me recount ke baad Piyush Kanodia (BJP) vijeta ghoshit (margin 316) — JagranJosh ki ECI-sourced list me purana naam tha.
// Vartaman sitting (Oct 2026): BJP 209, TMC 80, INC 2, AJUP 1, CPI(M) 1, AISF 1 = 294. Koi seat khaali NAHI.
// CM: Suvendu Adhikari (BJP, Bhabanipur) — shapath 9 May 2026; Mamata Banerjee ko Bhabanipur me 15,105 maton se haraya.
// Speaker: Rathindra Bose (BJP, Cooch Behar Dakshin) — 15 May 2026 nirvirodh.
// Dy CM / Dy Speaker: abhi tak ghoshit/pusht nahi (Oct 2026).
// LoP VIVADIT: Speaker ne rebel-TMC ke Ritabrata Banerjee ko 3 Jun 2026 se LoP mana; Calcutta HC ne 18 Aug 2026 ko "for now" jaari rakhne diya.
// TMC vidrohi gut: Sarvochch Nyayalaya ne Sep 2026 me Speaker se 10 naam-darj rebel MLAs ke disqualification yachikaon par samay par faisla karne ko kaha;
// in 10 ke records me party = TMC (ECI 2026 parinaam ke anusaar) + disclosure backgroundNote me.
// Fund: BEUP — Rs 1 crore/seat/varsh (June 2026 budget se).
